from urllib.parse import urlsplit, urlunsplit, parse_qsl


def _host_matches(host: str | None, match_value: str) -> bool:
    """host ルールの適合判定"""
    if host is None:
        return False

    host = host.lower()
    match_value = match_value.lower()

    if match_value.startswith("*."):
        base = match_value[2:]
        # ドメインそのものは除外し、厳密なサブドメインだけを許可
        return host != base and host.endswith("." + base)

    return host == match_value


def _replace_host_preserving_port(parsed, new_host: str):
    """ホストだけを置換し、ユーザー情報とポートは維持する"""
    netloc = parsed.netloc

    userinfo = ""
    authority = netloc

    if "@" in authority:
        userinfo, authority = authority.rsplit("@", 1)
        userinfo += "@"

    # 元のポート部分を取り出す
    port = ""
    if authority.startswith("["):
        # IPv6 アドレス
        closing_bracket = authority.find("]")
        if closing_bracket != -1:
            rest = authority[closing_bracket + 1:]
            if rest.startswith(":"):
                port = rest
    else:
        # 通常のホスト名
        if ":" in authority:
            candidate = authority.rsplit(":", 1)[1]
            if candidate.isdigit():
                port = ":" + candidate

    # IPv6 のホスト名は [] で囲む
    if ":" in new_host and not (
        new_host.startswith("[") and new_host.endswith("]")
    ):
        new_host = f"[{new_host}]"

    new_netloc = userinfo + new_host + port
    return parsed._replace(netloc=new_netloc)


def _rewrite_one(rules, url):
    parsed = urlsplit(url)

    for rule in rules:
        match_type = rule["match_type"]
        match_value = rule["match_value"]
        action = rule["action"]

        matched = False

        if match_type == "path_prefix":
            matched = parsed.path.startswith(match_value)

        elif match_type == "host":
            matched = _host_matches(parsed.hostname, match_value)

        elif match_type == "query_param":
            query_names = {
                name for name, _ in parse_qsl(
                    parsed.query,
                    keep_blank_values=True
                )
            }
            matched = match_value in query_names

        if not matched:
            continue

        # 最初に適合したルールを使い、以後のルールは確認しない
        if action == "block":
            return None

        action_value = rule["action_value"]

        if action == "strip_prefix":
            new_path = parsed.path
            if new_path.startswith(action_value):
                new_path = new_path[len(action_value):]

            if new_path == "":
                new_path = "/"

            parsed = parsed._replace(path=new_path)

        elif action == "redirect_host":
            parsed = _replace_host_preserving_port(parsed, action_value)

        elif action == "add_query_param":
            if parsed.query:
                new_query = parsed.query + "&" + action_value
            else:
                new_query = action_value

            parsed = parsed._replace(query=new_query)

        return urlunsplit(parsed)

    # どのルールにも適合しなかった場合
    return url


def apply_rewrite_rules(rules, urls):
    """
    rules: 辞書の順序付きリスト
    urls: URL のリスト

    各 URL について、最初に適合したルールだけを適用する。
    block された URL は None とする。
    """
    return [_rewrite_one(rules, url) for url in urls]
```

使用例:

```python
rules = [
    {
        "match_type": "path_prefix",
        "match_value": "/old-api/",
        "action": "strip_prefix",
        "action_value": "/old-api",
    }
]

urls = ["http://api.example.com/old-api/users"]

print(apply_rewrite_rules(rules, urls))
# ['http://api.example.com/users']
```

`redirect_host` では、スキーム、ポート、パス、クエリ、フラグメントを維持したままホストだけを置き換えます。

